using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
namespace DoomSNESed {
    // Retail USA assets, identified byte-for-byte against DoomFX's COMP and CUT data.
    // Weapon master tiles are shared by animation frames; their layout is retained.
    public static class HudAssets {
        static readonly int[] Addresses={0x1fe5b3,0x1fa9a4,0x19fbdd,0x1e5bb4,0x1feb07,0x1df63f,0x1f711d,0x1ecaed,0x1f238e,0x1fbe88,0x1f4b66,0x1f649d,0x1fb468,0x1ffdec};
        static readonly int[] Sizes={3168,3456,1280,12288,2048,2496,3072,6656,3488,2464,3232,3200,2592,192};
        static readonly int[] Widths={128,216,160,192,128,128,128,128,128,128,128,128,128,24};
        static readonly string[] Names={"Text font (ASCII 32–130)","Status bar background","Status bar digits","Faces (32 faces, 24 x 32 each)","Status bar weapon indicators","Fist master tiles","Pistol master tiles","Shotgun master tiles","Chainsaw master tiles","Chaingun master tiles","Rocket launcher master tiles","Plasma rifle master tiles","BFG9000 master tiles","Status bar keys"};
        static readonly int[][] Pointers={new[]{0x1f5d84,0x1ff08f,0x1ff5f3},new[]{0x1fa3cc},new[]{0x1fa3ec},new[]{0x1fa1a0},new[]{0x1fa1c0},new[]{0x1fa1b0}};
        static int Index(int screen){Bin.Require(screen>=6&&screen<6+Sizes.Length,"Unknown font / HUD asset.");return screen-6;}
        static int Size(byte[] rom,int i){return rom!=null&&i>=5&&i<13?RomLayout.WeaponBytes(rom,i-5,Sizes[i]):Sizes[i];}
        public static IEnumerable<NativeGraphic> All(Rom rom=null){yield return PickupFont.Asset();for(int i=0;i<Sizes.Length;i++)yield return new NativeGraphic{Screen=i+6,Name=Names[i],Width=Widths[i],Height=((Size(rom==null?null:rom.Bytes,i)/32+Widths[i]/8-1)/(Widths[i]/8))*8};}
        public static byte[] Data(byte[] rom,int screen){int i=Index(screen);return i<5||i==13?NativeCompression.Decode(rom,GraphicsAssets.Address(rom,RomLayout.At(rom,Pointers[i==13?5:i][0]))):rom.Skip(RomLayout.At(rom,Addresses[i])).Take(Size(rom,i)).ToArray();}
        public static byte[] Pixels(byte[] data,int width,int height){var pixels=new byte[width*height];for(int t=0;t<data.Length/32;t++)for(int y=0;y<8;y++)for(int x=0;x<8;x++)for(int p=0;p<4;p++)pixels[(t/(width/8)*8+y)*width+t%(width/8)*8+x]|=(byte)(((data[t*32+p/2*16+y*2+p%2]>>(7-x))&1)<<p);return pixels;}
        public static byte[] Tiles(GraphicReplacement asset,byte[] rom=null){int i=Index(asset.Screen);Bin.Require(asset.Width==Widths[i]&&asset.Height==((Size(rom,i)/32+Widths[i]/8-1)/(Widths[i]/8))*8&&asset.Pixels!=null&&asset.Pixels.Length==asset.Width*asset.Height&&asset.Pixels.All(v=>v<16),"Invalid native font / HUD dimensions or colours.");var data=new byte[Size(rom,i)];for(int t=0;t<data.Length/32;t++)for(int y=0;y<8;y++)for(int x=0;x<8;x++)for(int p=0;p<4;p++)data[t*32+p/2*16+y*2+p%2]|=(byte)(((asset.Pixels[(t/(asset.Width/8)*8+y)*asset.Width+t%(asset.Width/8)*8+x]>>p)&1)<<(7-x));return data;}
        static Color Colour(Rom rom,int screen,int index,int palette){if(screen==6)return index==0?Color.Transparent:index==7?Color.Black:Color.FromArgb(index*17,index*17,index*17);return index==0?Color.Transparent:AssetPreview.Palette(rom,palette+index);}
        static int[] Palettes(Rom rom,int screen){int i=Index(screen);if(i==13)return Enumerable.Range(0,6).Select(t=>t%3==1?240:224).ToArray();if(i>=5)return WeaponTiles.Palettes(rom.Bytes,i-5,Size(rom.Bytes,i)/32).Select(p=>128+p*16).ToArray();return Enumerable.Repeat(screen==7?0:screen==8?224:screen==10?144:128,Sizes[i]/32).ToArray();}
        public static Bitmap Preview(Rom rom,int screen,GraphicReplacement replacement){if(screen==PickupFont.Screen)return PickupFont.Preview(rom,replacement);var asset=All(rom).First(a=>a.Screen==screen);byte[] pixels=replacement==null?Pixels(Data(rom.Bytes,screen),asset.Width,asset.Height):replacement.Pixels;int[] palettes=Palettes(rom,screen);var image=new Bitmap(asset.Width,asset.Height);for(int y=0;y<asset.Height;y++)for(int x=0;x<asset.Width;x++)image.SetPixel(x,y,Colour(rom,screen,pixels[y*asset.Width+x],palettes[Math.Min(palettes.Length-1,y/8*(asset.Width/8)+x/8)]));return image;}
        public static GraphicReplacement Import(Rom rom,NativeGraphic asset,string path){if(asset.Screen==PickupFont.Screen)return PickupFont.Import(rom,path);using(var image=new Bitmap(path)){Bin.Require(image.Width==asset.Width&&image.Height==asset.Height,"This asset requires exactly "+asset.Width+" x "+asset.Height+" pixels. Export the original as a template.");int[] palettes=Palettes(rom,asset.Screen);byte[] original=Pixels(Data(rom.Bytes,asset.Screen),asset.Width,asset.Height),pixels=new byte[original.Length];for(int y=0;y<asset.Height;y++)for(int x=0;x<asset.Width;x++){int pos=y*asset.Width+x;Color c=image.GetPixel(x,y);if(c.A<128){pixels[pos]=0;continue;}int best=int.MaxValue,chosen=original[pos];for(int k=0;k<16;k++){int index=k==0?original[pos]:k<=original[pos]?k-1:k; if(index==0)continue;Color q=Colour(rom,asset.Screen,index,palettes[Math.Min(palettes.Length-1,y/8*(asset.Width/8)+x/8)]);int d=(c.R-q.R)*(c.R-q.R)+(c.G-q.G)*(c.G-q.G)+(c.B-q.B)*(c.B-q.B);if(d<best){best=d;chosen=index;}}pixels[pos]=(byte)chosen;}return new GraphicReplacement{Screen=asset.Screen,Width=asset.Width,Height=asset.Height,Pixels=pixels};}}
        public static void Apply(byte[] target,GraphicReplacement asset,List<Section> free,ref int used){if(asset.Screen==PickupFont.Screen){PickupFont.Apply(target,asset);return;}int i=Index(asset.Screen);byte[] data=Tiles(asset,target);if(Data(target,asset.Screen).SequenceEqual(data))return;if(i>=5&&i!=13){Buffer.BlockCopy(data,0,target,RomLayout.At(target,Addresses[i]),data.Length);return;}var raw=new byte[data.Length+4];Bin.W16(raw,2,data.Length);Buffer.BlockCopy(data,0,raw,4,data.Length);byte[] packed=NativeCompression.Encode(data);int address=GraphicsAssets.Store(target,packed.Length<raw.Length?packed:raw,free,ref used);foreach(int oldPointer in Pointers[i==13?5:i]){int pointer=RomLayout.At(target,oldPointer);Bin.W16(target,pointer,address);target[pointer+2]=GraphicsAssets.CpuBank(address);}}
    }
}



